import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;
        int t = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < t; k++) {
            int n = sc.nextInt();
            String s = sc.next();
            int first = -1, last = -1;
            for (int i = 0; i < s.length(); i++) {
                char ch = s.charAt(i);
                if (ch == 'o' || ch == 'O' || ch == '0') {
                    if (first == -1) first = i;
                    last = i;
                }
            }
            if (k > 0) sb.append((char)10);
            sb.append(first == -1 ? "0" : Integer.toString(last - first + 1));
        }
        System.out.print(sb);
    }
}

