import sys


def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:1 + n]

    # pos[v] 表示巡检序号 v 所在的下标。
    pos = [0] * (n + 1)
    for index, value in enumerate(p, start=1):
        pos[value] = index

    left = 0
    for value in range(1, n):
        if pos[value + 1] < pos[value]:
            left += 1

    right = (n - 1) - left
    print(left, right)


if __name__ == "__main__":
    solve()

