import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLong()) return;
        int p = (int) sc.nextLong();
        long mod = sc.nextLong();
        long[] values = new long[p];
        for (int i = 0; i < p; i++) values[i] = sc.nextLong();
        if (p == 1) { System.out.println("1 1 0"); return; }
        long[] diff = new long[p - 1];
        for (int i = 0; i + 1 < p; i++) diff[i] = Math.floorMod(values[i + 1] - values[i], mod);
        int bestLen = 1, bestStart = 0, curStart = 0;
        for (int i = 1; i < p - 1; i++) {
            if (diff[i] != diff[i - 1]) curStart = i;
            int curLen = i - curStart + 1;
            if (curLen > bestLen) { bestLen = curLen; bestStart = curStart; }
        }
        System.out.println((bestLen + 1) + " " + (bestStart + 1) + " " + diff[bestStart]);
    }
}

import java.util.*;
public class Main {
    static List<List<Long>> subsetSumsByCount(long[] values) {
        int size = values.length;
        int limit = 1 << size;
        long[] sums = new long[limit];
        List<List<Long>> buckets = new ArrayList<>();
        for (int i = 0; i <= size; i++) buckets.add(new ArrayList<>());
        buckets.get(0).add(0L);
        for (int mask = 1; mask < limit; mask++) {
            int lowbit = mask & -mask;
            int index = Integer.numberOfTrailingZeros(lowbit);
            int previous = mask ^ lowbit;
            sums[mask] = sums[previous] + values[index];
            buckets.get(Integer.bitCount(mask)).add(sums[mask]);
        }
        return buckets;
    }
    static long minimumGap(long[] values) {
        int n = values.length;
        int middle = n / 2;
        int needCount = n / 2;
        long total = 0;
        for (long v : values) total += v;
        List<List<Long>> left = subsetSumsByCount(Arrays.copyOfRange(values, 0, middle));
        List<List<Long>> right = subsetSumsByCount(Arrays.copyOfRange(values, middle, n));
        List<long[]> doubledRight = new ArrayList<>();
        for (List<Long> bucket : right) {
            long[] arr = new long[bucket.size()];
            for (int i = 0; i < arr.length; i++) arr[i] = 2 * bucket.get(i);
            Arrays.sort(arr);
            doubledRight.add(arr);
        }
        long best = total;
        for (int leftCount = 0; leftCount < left.size(); leftCount++) {
            int rightCount = needCount - leftCount;
            if (rightCount < 0 || rightCount >= doubledRight.size()) continue;
            long[] candidates = doubledRight.get(rightCount);
            for (long leftSum : left.get(leftCount)) {
                long target = total - 2 * leftSum;
                int position = lowerBound(candidates, target);
                if (position < candidates.length) best = Math.min(best, candidates[position] - target);
                if (position > 0) best = Math.min(best, target - candidates[position - 1]);
                if (best == 0) return 0;
            }
        }
        return best;
    }
    static int lowerBound(long[] a, long target) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] < target) lo = mid + 1; else hi = mid; }
        return lo;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int q = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < q; t++) {
