        for (Set<Integer> rec : records) for (int v : rec) singleton.merge(v, 1, Integer::sum);
        Map<List<Integer>, Integer> support = new HashMap<>();
        List<List<Integer>> level = new ArrayList<>();
        Integer[] keys = singleton.keySet().toArray(new Integer[0]);
        Arrays.sort(keys);
        for (int v : keys) { int cnt = singleton.get(v); if (cnt >= minCnt) { List<Integer> is = new ArrayList<>(); is.add(v); level.add(is); support.put(is, cnt); } }
        List<List<Integer>> allFrequent = new ArrayList<>();
        while (!level.isEmpty()) {
            allFrequent.addAll(level);
            List<List<Integer>> candidates = generateCandidates(level);
            List<List<Integer>> next = new ArrayList<>();
            for (List<Integer> cand : candidates) {
                int cnt = 0;
                for (Set<Integer> rec : records) { boolean all = true; for (int v : cand) if (!rec.contains(v)) { all = false; break; } if (all) cnt++; }
                if (cnt >= minCnt) { next.add(cand); support.put(cand, cnt); }
            }
            level = next;
        }
        allFrequent.sort((x, y) -> { if (x.size() != y.size()) return x.size() - y.size(); for (int i = 0; i < x.size(); i++) { int c = x.get(i).compareTo(y.get(i)); if (c != 0) return c; } return 0; });
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int idx = 0; idx < allFrequent.size(); idx++) {
            if (idx > 0) sb.append(',');
            List<Integer> is = allFrequent.get(idx);
            sb.append('[');
            for (int j = 0; j < is.size(); j++) { if (j > 0) sb.append(','); sb.append(is.get(j)); }
            sb.append(']').append(',').append(support.get(is));
            sb.append(']');
        }
        sb.append(']');
        System.out.println(sb);
    }
}

