import sys
import re

def solve(line):
    tokens = line.split()
    if len(tokens) != 4:
        return "-1 -1"
    for t in tokens:
        if not re.fullmatch(r"[0-9]+", t):
            return "-1 -1"
    layers, max_load, m, cards = (int(t) for t in tokens)
    if min(layers, max_load, m, cards) < 1:
        return "-1 -1"

    best_pp = -1
    for pp in range(1, cards + 1):
        if layers % pp == 0 and layers // pp <= max_load:
            best_pp = pp
            break
    if best_pp == -1:
        return "-1 -1"

    # 整数算术四舍五入到4位小数
    num = (best_pp - 1) * 10000
    den = m + best_pp - 1
    q, r = divmod(num, den)
    if 2 * r >= den:
        q += 1
    return f"{best_pp} {q // 10000}.{q % 10000:04d}"

line = sys.stdin.readline()
print(solve(line))

