import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static int lowerBound(long[] arr, long target, int from, int to) {
        int lo = from;
        int hi = to;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        int stageCount = fs.nextInt();
        long limit = fs.nextLong();
        long[] times = new long[n];
        for (int i = 0; i < n; i++) times[i] = fs.nextLong();
        long[] comm = new long[Math.max(n - 1, 0)];
        if (n > 1) {
            for (int i = 0; i < n - 1; i++) comm[i] = fs.nextLong();
        }
        long maxTime = 0;
        for (long v : times) maxTime = Math.max(maxTime, v);
        if (maxTime > limit) {
            System.out.println(-1);
            return;
        }
        long[] prefix = new long[n + 1];
        for (int i = 1; i <= n; i++) prefix[i] = prefix[i - 1] + times[i - 1];
        final long INF = (long) 1e18;
        long[] dpPrev = new long[n + 1];
        Arrays.fill(dpPrev, INF);
        for (int i = 1; i <= n; i++) {
            if (prefix[i] <= limit) dpPrev[i] = 0;
        }
        for (int stages = 2; stages <= stageCount; stages++) {
            long[] dpCur = new long[n + 1];
            Arrays.fill(dpCur, INF);
            PriorityQueue<long[]> heap = new PriorityQueue<>(new Comparator<long[]>() {
                public int compare(long[] a, long[] b) {
                    if (a[0] != b[0]) return Long.compare(a[0], b[0]);
                    return Long.compare(a[1], b[1]);
                }
            });
            for (int i = stages; i <= n; i++) {
                int k = i - 1;
                if (dpPrev[k] < INF) {
                    long candidateCost = dpPrev[k] + comm[k - 1];
                    heap.add(new long[]{candidateCost, k});
                }
                int lower = lowerBound(prefix, prefix[i] - limit, 0, i);
                while (!heap.isEmpty() && heap.peek()[1] < lower) heap.poll();
                if (!heap.isEmpty()) dpCur[i] = heap.peek()[0];
            }
            dpPrev = dpCur;
        }
        long answer = dpPrev[n];
        System.out.println(answer == INF ? -1 : answer);
    }
}

