    static boolean feasible(long[] weights, long cap, int k) {
        int segments = 1;
        long current = 0;
        for (long w : weights) {
            if (current + w <= cap) {
                current += w;
            } else {
                segments++;
                current = w;
                if (segments > k) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
