        int k = fs.nextInt();
        long left = 0;
        long right = 0;
        for (long w : weights) {
            left = Math.max(left, w);
            right += w;
        }
        while (left < right) {
            long mid = (left + right) / 2;
            if (feasible(weights, mid, k)) right = mid;
            else left = mid + 1;
        }
        System.out.println(left);
    }
}

import java.io.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    static final int QMAX = 127;
    static final int MAX_B = 30;

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Fraction {
        BigInteger num;
        BigInteger den;
        Fraction(BigInteger n, BigInteger d) {
            if (d.signum() < 0) {
                n = n.negate();
                d = d.negate();
            }
            BigInteger g = n.gcd(d);
            if (g.signum() != 0) {
                n = n.divide(g);
                d = d.divide(g);
            }
            num = n;
            den = d;
        }
        int compareTo(Fraction o) {
            return num.multiply(o.den).compareTo(o.num.multiply(den));
        }
    }

    static Fraction parseFraction(String s) {
        BigDecimal bd = new BigDecimal(s.trim());
        BigInteger unscaled = bd.unscaledValue();
        int scale = bd.scale();
        BigInteger num;
        BigInteger den;
        if (scale >= 0) {
            num = unscaled;
            den = BigInteger.TEN.pow(scale);
        } else {
            num = unscaled.multiply(BigInteger.TEN.pow(-scale));
            den = BigInteger.ONE;
        }
        return new Fraction(num, den);
    }

    static Fraction divide(Fraction a, Fraction b) {
        return new Fraction(a.num.multiply(b.den), a.den.multiply(b.num));
    }

    static BigInteger roundHalfAway(Fraction f) {
        BigInteger n = f.num;
        BigInteger d = f.den;
        boolean neg = n.signum() < 0;
        BigInteger absN = n.abs();
        BigInteger[] qr = absN.divideAndRemainder(d);
        BigInteger q = qr[0];
        if (qr[1].shiftLeft(1).compareTo(d) >= 0) {
            q = q.add(BigInteger.ONE);
        }
        return neg ? q.negate() : q;
    }

    static class ColumnResult {
        long[] quantized;
        long a;
        long b;
        ColumnResult(long[] quantized, long a, long b) {
            this.quantized = quantized;
            this.a = a;
            this.b = b;
        }
    }

    static ColumnResult quantizeColumn(String[] tokens) {
        int len = tokens.length;
        Fraction[] column = new Fraction[len];
        for (int i = 0; i < len; i++) column[i] = parseFraction(tokens[i]);
        Fraction maximum = null;
        for (Fraction f : column) {
            Fraction abs = new Fraction(f.num.abs(), f.den);
            if (maximum == null || abs.compareTo(maximum) > 0) maximum = abs;
        }
        if (maximum.num.signum() == 0) {
            long[] zeros = new long[len];
            return new ColumnResult(zeros, 0, MAX_B);
        }
        Fraction scale = new Fraction(maximum.num, maximum.den.multiply(BigInteger.valueOf(QMAX)));
        long[] quantized = new long[len];
        for (int i = 0; i < len; i++) {
            quantized[i] = roundHalfAway(divide(column[i], scale)).longValue();
        }
        Long chosenB = null;
        Long chosenA = null;
        for (int b = MAX_B; b >= 0; b--) {
            Fraction scaled = new Fraction(scale.num.shiftLeft(b), scale.den);
            BigInteger av = roundHalfAway(scaled);
            if (av.signum() >= 0 && av.compareTo(BigInteger.valueOf(QMAX)) <= 0) {
                chosenB = (long) b;
                chosenA = av.longValue();
                break;
            }
        }
        if (chosenB == null) throw new RuntimeException("unrepresentable");
        return new ColumnResult(quantized, chosenA, chosenB);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int m = Integer.parseInt(t);
        int k = fs.nextInt();
        int n = fs.nextInt();
        long[][] qa = new long[m][k];
        long[] aa = new long[m];
        long[] ba = new long[m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < k; j++) qa[i][j] = fs.nextInt();
            aa[i] = fs.nextInt();
            ba[i] = fs.nextInt();
        }
        ColumnResult[] cols = new ColumnResult[n];
        for (int i = 0; i < n; i++) {
            String[] toks = new String[k];
            for (int j = 0; j < k; j++) toks[j] = fs.next();
            cols[i] = quantizeColumn(toks);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) {
            StringBuilder line = new StringBuilder();
            boolean first = true;
            for (int j = 0; j < n; j++) {
                ColumnResult col = cols[j];
                long qc = 0;
                for (int x = 0; x < k; x++) qc += qa[i][x] * col.quantized[x];
                long ab = aa[i] * col.a;
                long bb = ba[i] + col.b;
                if (!first) line.append(' ');
                first = false;
                line.append(qc).append(' ').append(ab).append(' ').append(bb);
            }
            if (i > 0) sb.append(NL);
            sb.append(line);
        }
        System.out.print(sb);
    }
}

