import java.io.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static final char NL = (char) 10;
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static BigInteger[] scaled(String[] values) {
        int len = values.length;
        BigDecimal[] nums = new BigDecimal[len];
        int places = 0;
        for (int i = 0; i < len; i++) {
            nums[i] = new BigDecimal(values[i].trim());
            int sc = nums[i].scale();
            if (sc > places) places = sc;
        }
        BigInteger[] result = new BigInteger[len];
        for (int i = 0; i < len; i++) {
            BigInteger coeff = nums[i].unscaledValue();
            int exponent = -nums[i].scale();
            result[i] = coeff.multiply(BigInteger.TEN.pow(exponent + places));
        }
        return result;
    }

    static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        int m = fs.nextInt();
        String epsText = fs.next();
        int minPts = fs.nextInt();
        String[] tokens = new String[1 + 2 * n];
        tokens[0] = epsText;
        for (int i = 0; i < 2 * n; i++) tokens[1 + i] = fs.next();
        BigInteger[] values = scaled(tokens);
        BigInteger radius = values[0];
        BigInteger[] xs = new BigInteger[n];
        BigInteger[] ys = new BigInteger[n];
        for (int i = 0; i < n; i++) {
            xs[i] = values[1 + 2 * i];
            ys[i] = values[2 + 2 * i];
        }
        BigInteger r2 = radius.multiply(radius);
        List<List<Integer>> neighbors = new ArrayList<>();
        for (int i = 0; i < n; i++) neighbors.add(new ArrayList<Integer>());
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                BigInteger dx = xs[i].subtract(xs[j]);
                BigInteger dy = ys[i].subtract(ys[j]);
                BigInteger d2 = dx.multiply(dx).add(dy.multiply(dy));
                if (d2.compareTo(r2) <= 0) neighbors.get(i).add(j);
            }
        }
        boolean[] core = new boolean[n];
        for (int i = 0; i < n; i++) core[i] = neighbors.get(i).size() >= minPts;
        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        for (int i = 0; i < n; i++) {
            if (!core[i]) continue;
            for (int j : neighbors.get(i)) {
                if (core[j]) {
                    int a = find(parent, i);
                    int b = find(parent, j);
                    if (a != b) {
                        if (size[a] < size[b]) {
                            int tmp = a;
                            a = b;
                            b = tmp;
                        }
                        parent[b] = a;
                        size[a] += size[b];
                    }
                }
            }
        }
        List<Set<Integer>> memberships = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j : neighbors.get(i)) {
                if (core[j]) set.add(find(parent, j));
            }
            memberships.add(set);
        }
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < m; q++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            Set<Integer> first = memberships.get(a);
            Set<Integer> second = memberships.get(b);
            if (first.size() > second.size()) {
                Set<Integer> tmp = first;
                first = second;
                second = tmp;
            }
            int ans = 0;
            for (int root : first) {
                if (second.contains(root)) {
                    ans = 1;
                    break;
                }
            }
            if (q > 0) sb.append(NL);
            sb.append(ans);
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static long[] maximize(long[] a, long[] b, long budget) {
        int n = a.length;
        int left = 0;
        long memory = 0;
        long score = 0;
        long ordinary = 0;
        for (int right = 0; right < n; right++) {
            memory += b[right];
            score += a[right];
            while (left <= right && memory > budget) {
                memory -= b[left];
                score -= a[left];
                left++;
            }
            ordinary = Math.max(ordinary, score);
        }
        left = 0;
        memory = 0;
        score = 0;
        long compressed = ordinary;
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        for (int right = 0; right < n; right++) {
            memory += b[right];
            score += a[right];
            while (!queue.isEmpty()) {
                int last = queue.peekLast();
                boolean ge;
                if (a[last] != a[right]) {
                    ge = a[last] > a[right];
                } else {
                    ge = b[last] <= b[right];
                }
                if (ge) queue.pollLast();
                else break;
            }
            queue.addLast(right);
            while (!queue.isEmpty() && memory - (b[queue.peekFirst()] + 1) / 2 > budget) {
                if (queue.peekFirst() == left) queue.pollFirst();
                memory -= b[left];
                score -= a[left];
                left++;
            }
            if (!queue.isEmpty()) {
                compressed = Math.max(compressed, score - a[queue.peekFirst()]);
            }
        }
        return new long[]{ordinary, compressed};
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        String t = fs.next();
        if (t == null) return;
        int n = Integer.parseInt(t);
        long budget = fs.nextLong();
        long[] a = new long[n];
        long[] b = new long[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextLong();
        for (int i = 0; i < n; i++) b[i] = fs.nextLong();
        long[] result = maximize(a, b, budget);
        StringBuilder sb = new StringBuilder();
        sb.append(result[0]).append(' ').append(result[1]);
        System.out.println(sb);
    }
}

import java.io.*;
import java.util.*;
import java.util.Locale;

public class Main {
    static final int D_MODEL = 4;
    static final int D_K = 2;
    static final double EPS = 1e-5;
    static class In {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() { while (!st.hasMoreTokens()) { String l=null; try { l=br.readLine(); } catch (IOException e) { throw new RuntimeException(e); } if (l==null) return null; st=new StringTokenizer(l); } return st.nextToken(); }
        double nd() { return Double.parseDouble(next()); }
    }
    static double[] layerNorm(double[] values) {
        double mean = 0.0;
        for (double v : values) mean += v;
        mean /= D_MODEL;
        double variance = 0.0;
        for (double v : values) variance += (v - mean) * (v - mean);
        variance /= D_MODEL;
        double scale = Math.sqrt(variance + EPS);
        double[] out = new double[D_MODEL];
        for (int i = 0; i < D_MODEL; i++) out[i] = (values[i] - mean) / scale;
        return out;
    }
    public static void main(String[] args) {
        In in = new In();
        double[] values = new double[2 * D_MODEL];
        for (int i = 0; i < values.length; i++) values[i] = in.nd();
        double[][] x = new double[2][D_MODEL];
        for (int i = 0; i < D_MODEL; i++) x[0][i] = values[i];
        for (int i = 0; i < D_MODEL; i++) x[1][i] = values[D_MODEL + i];
        double[][][] headOut = new double[2][2][D_K];
        for (int hi = 0; hi < 2; hi++) {
            int start = hi * D_K;
            double[][] headValues = new double[2][D_K];
            for (int tok = 0; tok < 2; tok++) for (int d = 0; d < D_K; d++) headValues[tok][d] = x[tok][start + d];
            for (int qi = 0; qi < 2; qi++) {
                double[] scores = new double[2];
                for (int kj = 0; kj < 2; kj++) {
                    double dot = 0.0;
                    for (int d = 0; d < D_K; d++) dot += headValues[qi][d] * headValues[kj][d];
                    scores[kj] = dot / Math.sqrt(D_K);
                }
                double maximum = scores[0];
                for (int kj = 1; kj < 2; kj++) if (scores[kj] > maximum) maximum = scores[kj];
                double[] w = new double[2];
                double total = 0.0;
                for (int kj = 0; kj < 2; kj++) { w[kj] = Math.exp(scores[kj] - maximum); total += w[kj]; }
                for (int d = 0; d < D_K; d++) {
                    double sum = 0.0;
                    for (int kj = 0; kj < 2; kj++) sum += w[kj] * headValues[kj][d];
                    headOut[hi][qi][d] = sum / total;
                }
            }
        }
        double[][] attention = new double[2][D_MODEL];
        for (int tok = 0; tok < 2; tok++) {
            for (int d = 0; d < D_K; d++) {
                attention[tok][d] = headOut[0][tok][d];
                attention[tok][D_K + d] = headOut[1][tok][d];
            }
        }
        double[][] hidden = new double[2][D_MODEL];
        for (int tok = 0; tok < 2; tok++) {
            double[] pre = new double[D_MODEL];
            for (int d = 0; d < D_MODEL; d++) pre[d] = x[tok][d] + attention[tok][d];
            hidden[tok] = layerNorm(pre);
        }
        double[][] output = new double[2][D_MODEL];
        for (int tok = 0; tok < 2; tok++) {
            double[] pre = new double[D_MODEL];
            for (int d = 0; d < D_MODEL; d++) pre[d] = hidden[tok][d] + Math.max(0.0, hidden[tok][d]);
            output[tok] = layerNorm(pre);
        }
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (int tok = 0; tok < 2; tok++) {
            for (int d = 0; d < D_MODEL; d++) {
                String text = String.format(Locale.US, "%.2f", output[tok][d]);
                if (text.equals("-0.00")) text = "0.00";
                if (!first) sb.append(' ');
                first = false;
                sb.append(text);
            }
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final double EPS = 1e-6;
    static class In {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() { while (!st.hasMoreTokens()) { String l=null; try { l=br.readLine(); } catch (IOException e) { throw new RuntimeException(e); } if (l==null) return null; st=new StringTokenizer(l); } return st.nextToken(); }
        int ni() { return Integer.parseInt(next()); }
    }
    static class Choice { int index; List<double[]> first, second; Choice(int i, List<double[]> a, List<double[]> b) { index=i; first=a; second=b; } }
    static double sse(List<double[]> pts) {
        int n = pts.size();
        double mx = 0.0, my = 0.0;
        for (double[] p : pts) { mx += p[0]; my += p[1]; }
        mx /= n; my /= n;
        double s = 0.0;
        for (double[] p : pts) { double dx = p[0] - mx, dy = p[1] - my; s += dx*dx + dy*dy; }
        return s;
    }
    static List<double[]> splitTwo(List<double[]> pts) {
        double[] left = pts.get(0);
        for (double[] p : pts) if (p[0] < left[0]) left = p;
        double[] right = pts.get(0);
        for (double[] p : pts) if (p[0] > right[0]) right = p;
        double[][] centers = {{left[0], left[1]}, {right[0], right[1]}};
        int[] labels = null;
        while (true) {
            int m = pts.size();
            int[] newLabels = new int[m];
            for (int i = 0; i < m; i++) {
                double[] p = pts.get(i);
                double d0 = (p[0]-centers[0][0])*(p[0]-centers[0][0]) + (p[1]-centers[0][1])*(p[1]-centers[0][1]);
                double d1 = (p[0]-centers[1][0])*(p[0]-centers[1][0]) + (p[1]-centers[1][1])*(p[1]-centers[1][1]);
                newLabels[i] = d0 < d1 ? 0 : 1;
            }
            if (labels != null && Arrays.equals(newLabels, labels)) break;
            labels = newLabels;
            double[] sums0 = {0,0}; int c0 = 0;
            double[] sums1 = {0,0}; int c1 = 0;
            for (int i = 0; i < m; i++) { double[] p = pts.get(i); if (labels[i] == 0) { sums0[0]+=p[0]; sums0[1]+=p[1]; c0++; } else { sums1[0]+=p[0]; sums1[1]+=p[1]; c1++; } }
            double cx0 = sums0[0]/c0, cy0 = sums0[1]/c0, cx1 = sums1[0]/c1, cy1 = sums1[1]/c1;
            double move = Math.max(Math.hypot(cx0-centers[0][0], cy0-centers[0][1]), Math.hypot(cx1-centers[1][0], cy1-centers[1][1]));
            centers = new double[][]{{cx0,cy0},{cx1,cy1}};
            if (move < EPS) break;
        }
        List<double[]> first = new ArrayList<>();
        List<double[]> second = new ArrayList<>();
        for (int i = 0; i < pts.size(); i++) { if (labels[i] == 0) first.add(pts.get(i)); else second.add(pts.get(i)); }
        List<double[]> res = new ArrayList<>(); res.add(first); res.add(second);
        return res;
    }
    static Choice chooseCluster(List<List<double[]>> clusters) {
        int bestIndex = -1;
        double bestGradient = 0.0;
        List<double[]> bestFirst = null, bestSecond = null;
        for (int idx = 0; idx < clusters.size(); idx++) {
            List<double[]> cluster = clusters.get(idx);
            if (cluster.size() < 2) continue;
            List<double[]> children = splitTwo(cluster);
            double gradient = sse(cluster) - sse(children.get(0)) - sse(children.get(1));
            boolean better = gradient > bestGradient + EPS;
            boolean tied = Math.abs(gradient - bestGradient) <= EPS;
            boolean larger = bestIndex == -1 || cluster.size() > clusters.get(bestIndex).size();
            if (bestIndex == -1 || better || (tied && larger)) { bestIndex = idx; bestGradient = gradient; bestFirst = children.get(0); bestSecond = children.get(1); }
        }
        return new Choice(bestIndex, bestFirst, bestSecond);
    }
    public static void main(String[] args) {
        In in = new In();
        int target = in.ni();
