def minimum_increment(n, m, length, b):
    cost = [[0] * m for _ in range(length)]
    groups = []
    for j in range(length):
        values = b[j:n:length]
        groups.append(values)
        row = cost[j]
        for value in values:
            for r in range(m):
                row[r] += (r - value) % m

    free_group = min(range(length), key=lambda j: len(groups[j]))
    inf = 10**30
    dp = [inf] * m
    dp[0] = 0

    for j in range(length):
        if j == free_group:
            continue
        next_dp = [inf] * m
        for r in set(groups[j]):
            add = cost[j][r]
            for s, old in enumerate(dp):
                if old < inf:
                    ns = (s + r) % m
                    candidate = old + add
                    if candidate < next_dp[ns]:
                        next_dp[ns] = candidate
        dp = next_dp

    return min(dp[s] + cost[free_group][(-s) % m] for s in range(m))


