import sys
from bisect import bisect_right


def min_days(n, monster_count, initial_power, health):
    thresholds = sorted(max(0, value - initial_power) for value in health)
    prefix = [0] * (n + 1)
    for i, value in enumerate(thresholds):
        prefix[i + 1] = prefix[i] + value

    def successful_days(stage):
        if stage < 0:
            return 0
        count = bisect_right(thresholds, stage)
        return count * (stage + 1) - prefix[count]

    low = 0
    high = thresholds[0] + monster_count - 1
    while low < high:
        middle = (low + high) // 2
        if successful_days(middle) >= monster_count:
            high = middle
        else:
            low = middle + 1

    stage = low
    remaining = monster_count - successful_days(stage - 1)
    power = initial_power + stage

    for index, value in enumerate(health, start=1):
        if value <= power:
            remaining -= 1
            if remaining == 0:
                return stage * n + index


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    test_cases = data[0]
    position = 1
    answers = []

    for _ in range(test_cases):
        n, monster_count, initial_power = data[position:position + 3]
        position += 3
        health = data[position:position + n]
        position += n
        answers.append(str(min_days(n, monster_count, initial_power, health)))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()

