            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            long w = Long.parseLong(st.nextToken());
            graph.get(u).add(new long[]{v, w});
            graph.get(v).add(new long[]{u, w});
        }
        long handTime = Long.parseLong(st.nextToken());
        long lockerTime = Long.parseLong(st.nextToken());
        int deliveryCount = Integer.parseInt(st.nextToken());
        int[] destinations = new int[deliveryCount];
        Set<Integer> useful = new LinkedHashSet<>();
        useful.add(station);
        for (int i = 0; i < deliveryCount; i++) {
