            int l = 2 * i + 1, r = 2 * i + 2;
            if (l < cnt && self[l] != -1) t += total[l];
            if (r < cnt && self[r] != -1) t += total[r];
            total[i] = t;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < cnt; i++) {
            if (i > 0) out.append('-');
            out.append(total[i]);
        }
        System.out.println(out);
    }
}

// 题目：无人机的安全距离检测
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static class Pt {
        long x, y;
        Pt(long x, long y) { this.x = x; this.y = y; }
    }

    static Pt[] ps;
    static long best;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());
        ps = new Pt[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            ps[i] = new Pt(Long.parseLong(st.nextToken()), Long.parseLong(st.nextToken()));
        }
        if (n < 2) { System.out.println("0.0000"); return; }
        Arrays.sort(ps, (a, b) -> a.x != b.x ? Long.compare(a.x, b.x) : Long.compare(a.y, b.y));
        best = Long.MAX_VALUE;
        rec(0, n - 1);
        System.out.printf(Locale.ROOT, "%.4f%n", Math.sqrt((double) best));
    }

    static long d2(Pt a, Pt b) {
        long dx = a.x - b.x, dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    static void rec(int l, int r) {
        if (r - l <= 3) {
            for (int i = l; i <= r; i++)
                for (int j = i + 1; j <= r; j++) {
                    long d = d2(ps[i], ps[j]);
                    if (d < best) best = d;
                }
            Arrays.sort(ps, l, r + 1, (a, b) -> Long.compare(a.y, b.y));
            return;
        }
        int mid = (l + r) >>> 1;
        long midx = ps[mid].x;
        rec(l, mid);
        rec(mid + 1, r);
        ArrayList<Pt> strip = new ArrayList<>();
        for (int i = l; i <= r; i++) {
            long dx = ps[i].x - midx;
            if (dx * dx < best) strip.add(ps[i]);
        }
        strip.sort((a, b) -> Long.compare(a.y, b.y));
        for (int i = 0; i < strip.size(); i++) {
            for (int j = i + 1; j < strip.size(); j++) {
                long dy = strip.get(j).y - strip.get(i).y;
                if (dy * dy >= best) break;
                long d = d2(strip.get(i), strip.get(j));
                if (d < best) best = d;
            }
        }
        Pt[] merged = new Pt[r - l + 1];
        int i = l, j = mid + 1, k = 0;
        while (i <= mid && j <= r) {
            if (ps[i].y <= ps[j].y) merged[k++] = ps[i++]; else merged[k++] = ps[j++];
        }
        while (i <= mid) merged[k++] = ps[i++];
        while (j <= r) merged[k++] = ps[j++];
        System.arraycopy(merged, 0, ps, l, merged.length);
    }
}

// 题目：数组划分
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int T = (int) in.nval;
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            in.nextToken(); int n = (int) in.nval;
            in.nextToken(); int k = (int) in.nval;
            int[] a = new int[n];
            for (int i = 0; i < n; i++) { in.nextToken(); a[i] = (int) in.nval; }
            int[] sorted = a.clone();
            Arrays.sort(sorted);
            int x = sorted[n - k]; // k-th largest
            ArrayList<Integer> big = new ArrayList<>();
            for (int i = 0; i < n; i++) if (a[i] >= x) big.add(i + 1);
            int prev = 0;
            for (int i = 0; i < k; i++) {
                int r = (i == k - 1) ? n : big.get(i);
                int l = prev + 1;
                out.append(l).append(' ').append(r).append('\n');
                prev = r;
            }
        }
        System.out.print(out);
    }
}

// 题目：火车出站问题
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;

public class Main {
    static class FastScanner {
        InputStream in;
        byte[] buf = new byte[1 << 16];
        int len = 0, ptr = 0;
        FastScanner(InputStream i) { in = i; }
        int read() {
            if (ptr >= len) {
                try { len = in.read(buf); } catch (IOException e) { len = -1; }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }
        int nextInt() {
            int c = read();
            while (c <= 32) { if (c == -1) return -1; c = read(); }
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int val = 0;
            while (c > 32) { val = val * 10 + (c - '0'); c = read(); }
            return val * sign;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        boolean[] inDeck = new boolean[n + 2];
        int maxAdded = 0, lo = 1, hi = 0;
        boolean empty = true;
        long front = 0;
        boolean ok = true;
        for (int i = 0; i < n && ok; i++) {
            int p = fs.nextInt();
            if (p > maxAdded) {
                int old = maxAdded;
                for (int v = old + 1; v <= p; v++) inDeck[v] = true;
                maxAdded = p;
                if (empty) lo = old + 1;
                hi = p;
                empty = false;
            } else {
                if (empty) { ok = false; break; }
                if (!inDeck[p]) { ok = false; break; }
            }
            if (p == hi) {
                inDeck[p] = false;
                front++;
                hi--;
                while (hi >= lo && !inDeck[hi]) hi--;
                if (hi < lo) empty = true;
            } else if (p == lo) {
                inDeck[p] = false;
                lo++;
                while (lo <= hi && !inDeck[lo]) lo++;
                if (lo > hi) empty = true;
            } else {
                ok = false;
            }
        }
        System.out.println(ok ? front : -1);
    }
}

