// 题目：多多的演唱会灯光方案
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static int idx(char c) {
        switch (c) {
            case 'D': return 0;
            case 'M': return 1;
            case 'T': return 2;
            case 'A': return 3;
            case 'O': return 4;
            default: return -1;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            int R = Integer.parseInt(br.readLine().trim());
            String s = br.readLine().trim();
            int n = s.length();
            int[] pref = new int[n + 1];
            for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + (idx(s.charAt(i)) >= 0 ? 0 : 1);
            int[] last = new int[5];
            Arrays.fill(last, -1);
            HashMap<Integer, Long> freq = new HashMap<>();
            int ptr = 0;
            long ans = 0;
            for (int r = 0; r < n; r++) {
                int ci = idx(s.charAt(r));
                if (ci >= 0) last[ci] = r;
                int good = Integer.MAX_VALUE;
                for (int k = 0; k < 5; k++) {
                    if (last[k] < 0) { good = -1; break; }
                    if (last[k] < good) good = last[k];
                }
                if (good < 0) continue;
                while (ptr <= good) {
                    freq.merge(pref[ptr], 1L, Long::sum);
                    ptr++;
                }
                int target = pref[r + 1] - R;
                ans += freq.getOrDefault(target, 0L);
            }
            out.append(ans).append('\n');
        }
        System.out.print(out);
    }
}

