    }

    static boolean inside(double x, double y) {
        double d1 = cross(x, y, p[0], p[1]);
        double d2 = cross(x, y, p[1], p[2]);
        double d3 = cross(x, y, p[2], p[0]);
        boolean neg = d1 < -1e-12 || d2 < -1e-12 || d3 < -1e-12;
        boolean pos = d1 > 1e-12 || d2 > 1e-12 || d3 > 1e-12;
        return !(neg && pos);
    }

    public static void main(String[] args) {
