import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            String s = br.readLine().trim();
            int n = s.length();
            long[] pre = new long[n + 1];
            for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + (s.charAt(i) - '0');
            long bestSum = -1; int bestI = -1;
            for (int i = 0; i < n; i++) {
                int dig = s.charAt(i) - '0';
                if (dig == 0) continue;
                long sum = pre[i] + (dig - 1) + 9L * (n - 1 - i);
                if (sum > bestSum) { bestSum = sum; bestI = i; }
            }
            StringBuilder r = new StringBuilder();
            if (bestI < 0) {
                r.append('0');
            } else {
                r.append(s, 0, bestI);
                r.append((char) ('0' + (s.charAt(bestI) - '0' - 1)));
                for (int k = 0; k < n - 1 - bestI; k++) r.append('9');
            }
            int p = 0;
            while (p < r.length() - 1 && r.charAt(p) == '0') p++;
            out.append(r.substring(p)).append('\n');
        }
        System.out.print(out);
    }
}

// 题目：第2题
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    static int nR, mS;
    static long[] rpos, spos;
    static int[] scap;
    static List<Edge>[] g;
    static int[] level, iter;

    static class Edge {
        int to, rev, cap;
        Edge(int to, int rev, int cap) { this.to = to; this.rev = rev; this.cap = cap; }
    }

    static void addEdge(int f, int t, int c) {
        g[f].add(new Edge(t, g[t].size(), c));
        g[t].add(new Edge(f, g[f].size() - 1, 0));
    }

    static boolean bfs(int s, int t) {
        Arrays.fill(level, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        level[s] = 0; q.add(s);
        while (!q.isEmpty()) {
            int v = q.poll();
            for (Edge e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.add(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    static int dfs(int v, int t, int f) {
        if (v == t) return f;
        for (; iter[v] < g[v].size(); iter[v]++) {
            Edge e = g[v].get(iter[v]);
            if (e.cap > 0 && level[v] + 1 == level[e.to]) {
                int d = dfs(e.to, t, Math.min(f, e.cap));
                if (d > 0) { e.cap -= d; g[e.to].get(e.rev).cap += d; return d; }
            }
        }
        return 0;
    }

    static boolean feasible(long E) {
        int nodes = 1 + nR + mS + 1;
        int S = 0, T = nodes - 1;
        g = new List[nodes];
        for (int i = 0; i < nodes; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < nR; i++) addEdge(S, 1 + i, 1);
        for (int j = 0; j < mS; j++) addEdge(1 + nR + j, T, scap[j]);
        for (int i = 0; i < nR; i++)
            for (int j = 0; j < mS; j++)
                if (Math.abs(rpos[i] - spos[j]) <= E) addEdge(1 + i, 1 + nR + j, 1);
        level = new int[nodes]; iter = new int[nodes];
        int flow = 0;
        while (bfs(S, T)) {
            Arrays.fill(iter, 0);
            int f;
            while ((f = dfs(S, T, Integer.MAX_VALUE)) > 0) {
                flow += f;
                if (flow >= nR) return true;
            }
        }
        return flow == nR;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int T = (int) in.nval;
        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < T; tc++) {
            in.nextToken(); nR = (int) in.nval;
            in.nextToken(); mS = (int) in.nval;
            rpos = new long[nR]; spos = new long[mS]; scap = new int[mS];
            for (int i = 0; i < nR; i++) { in.nextToken(); rpos[i] = (long) in.nval; }
            for (int j = 0; j < mS; j++) { in.nextToken(); spos[j] = (long) in.nval; }
            for (int j = 0; j < mS; j++) { in.nextToken(); scap[j] = (int) in.nval; }
            long totalCap = 0;
            for (int c : scap) totalCap += c;
            if (totalCap < nR) { out.append(-1).append('\n'); continue; }
            TreeSet<Long> set = new TreeSet<>();
            set.add(0L);
            for (int i = 0; i < nR; i++)
                for (int j = 0; j < mS; j++) set.add(Math.abs(rpos[i] - spos[j]));
            ArrayList<Long> list = new ArrayList<>(set);
            int lo = 0, hi = list.size() - 1, ansIdx = -1;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (feasible(list.get(mid))) { ansIdx = mid; hi = mid - 1; }
                else lo = mid + 1;
            }
            out.append(ansIdx < 0 ? -1 : list.get(ansIdx)).append('\n');
        }
        System.out.print(out);
    }
}

// 题目：第3题
// 算法：按题意模拟
// 模式：ACM（stdin/stdout）

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int N = (int) in.nval;
        int[] start = new int[N];
        for (int i = 0; i < N; i++) { in.nextToken(); start[i] = (int) in.nval; }
        int[][] d = new int[N][N];
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++) { in.nextToken(); d[i][j] = (int) in.nval; }
        int full = 1 << N;
        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[full][N];
        for (long[] row : dp) Arrays.fill(row, INF);
        for (int i = 0; i < N; i++) if (start[i] != -1) dp[1 << i][i] = start[i];
        for (int mask = 1; mask < full; mask++) {
            for (int last = 0; last < N; last++) {
                if (dp[mask][last] >= INF) continue;
                for (int nxt = 0; nxt < N; nxt++) {
                    if ((mask & (1 << nxt)) != 0) continue;
                    if (d[last][nxt] == -1) continue;
                    int nm = mask | (1 << nxt);
                    long cand = dp[mask][last] + d[last][nxt];
                    if (cand < dp[nm][nxt]) dp[nm][nxt] = cand;
                }
            }
        }
        long ans = INF;
        for (int last = 0; last < N; last++) ans = Math.min(ans, dp[full - 1][last]);
        System.out.println(ans >= INF ? -1 : ans);
    }
}
